import React from 'react';
import { Platform, Text } from 'react-native';
import renderer, { act } from 'react-test-renderer';
import {
  setSession, clearSession, isSignedIn, tryResumeSession, setRefreshHook, useSessionStore,
} from '../../src/gen/features/session';
import { useFieldScroll, focusFirstError } from '../../src/gen/validate';
import { I18nProvider, useI18n, RTL_LOCALES, LOCALES } from '../../src/gen/i18n';

describe('tryResumeSession against the probe', () => {
  /**
   * A COLD START: a refresh token on disk and no access token in memory.
   *
   * tryResumeSession returns true immediately for an already-signed-in session,
   * so setting one would skip the probe entirely. The store is dropped back to
   * signed-out without touching storage, which is exactly the state a relaunch
   * leaves behind.
   */
  const coldStart = async () => {
    await setSession('token', 'refresh');
    useSessionStore.setState({ accessToken: null, signedIn: false });
    setRefreshHook(async () => 'restored-access');
  };
  afterEach(async () => {
    setRefreshHook(null);
    await clearSession();
    mockReply.fail = false;
    mockReply.status = 200;
  });

  it('resumes when the probe confirms the restored session works', async () => {
    await coldStart();
    await expect(tryResumeSession()).resolves.toBe(true);
    expect(isSignedIn()).toBe(true);
  });
  it('gives up when there is nothing to refresh with', async () => {
    await clearSession();
    await expect(tryResumeSession()).resolves.toBe(false);
  });
  /**
   * A build whose Authentication panel names no validate operation has no probe
   * to fail, so it resumes on the refresh alone. Both assertions below are about
   * what happens WHEN there is one.
   */
  it('signs the user out when the probe says the session is no longer valid', async () => {
    for (const status of [401, 403]) {
      // eslint-disable-next-line no-await-in-loop
      await coldStart();
      mockReply.fail = true;
      mockReply.status = status;
      // eslint-disable-next-line no-await-in-loop
      const resumed = await tryResumeSession();
      if (!resumed) expect(isSignedIn()).toBe(false);
    }
  });
  it('KEEPS the session when the probe fails for any other reason', async () => {
    await coldStart();
    mockReply.fail = true;
    mockReply.status = 500;
    await tryResumeSession();
    // a 500 or a dropped connection says nothing about whether the session is
    // still valid — the next authenticated call will refresh if it truly expired
    expect(isSignedIn()).toBe(true);
  });
});

describe('focusFirstError inside a scroller', () => {
  function probe() {
    let handle: ReturnType<typeof useFieldScroll> | null = null;
    const Probe = () => { handle = useFieldScroll(); return <Text>probe</Text>; };
    let tree!: renderer.ReactTestRenderer;
    act(() => { tree = renderer.create(<Probe />); });
    return { handle: handle!, unmount: () => act(() => tree.unmount()) };
  }
  it('measures against the scroller inner view and scrolls the field into sight', () => {
    const p = probe();
    const scrollTo = jest.fn();
    const focus = jest.fn();
    const innerNode = {};
    // getInnerViewRef is what focusFirstError measures against: Fabric rejects
    // the numeric handle from getInnerViewNode, and react-native's own jest
    // setup defines nativeFabricUIManager — so a fake offering only the legacy
    // handle exercises a path the app never takes on the new architecture.
    // Both are supplied, the way a real ScrollView offers both.
    p.handle.scrollProps.ref({
      scrollTo,
      getInnerViewRef: () => innerNode,
      getInnerViewNode: () => innerNode,
    });
    p.handle.bind('f')({
      focus,
      measureLayout: (_n: unknown, ok: (x: number, y: number) => void) => ok(0, 400),
    });
    focusFirstError(['f'], { f: 'Required' });
    expect(scrollTo).toHaveBeenCalled();
    expect(focus).toHaveBeenCalled();
    p.unmount();
  });
  it('falls back to viewport arithmetic when measuring against the inner view fails', () => {
    const p = probe();
    const scrollTo = jest.fn();
    const focus = jest.fn();
    p.handle.scrollProps.ref({
      scrollTo,
      getInnerViewNode: () => ({}),
      measureInWindow: (cb: (x: number, y: number) => void) => cb(0, 50),
    });
    p.handle.scrollProps.onScroll({ nativeEvent: { contentOffset: { y: 30 } } } as never);
    p.handle.bind('f')({
      focus,
      // the failure callback is what a measure against a non-ancestor triggers
      measureLayout: (_n: unknown, _ok: unknown, fail: () => void) => fail(),
      measureInWindow: (cb: (x: number, y: number) => void) => cb(0, 300),
    });
    focusFirstError(['f'], { f: 'Required' });
    expect(focus).toHaveBeenCalled();
    p.unmount();
  });
  it('just focuses when the screen has no scroller to move', () => {
    const p = probe();
    const focus = jest.fn();
    p.handle.scrollProps.ref(null);
    p.handle.bind('f')({ focus });
    focusFirstError(['f'], { f: 'Required' });
    expect(focus).toHaveBeenCalled();
    p.unmount();
  });
});

describe('useI18n outside a provider', () => {
  it('answers with the context default rather than throwing', async () => {
    let ctx: ReturnType<typeof useI18n> | null = null;
    const Probe = () => { ctx = useI18n(); return <Text>{ctx.locale}</Text>; };
    let tree!: renderer.ReactTestRenderer;
    // no I18nProvider: a component rendered in isolation (a test, a storybook
    // entry, a screen mounted bare) must still be able to read the context
    act(() => { tree = renderer.create(<Probe />); });
    expect(LOCALES).toContain(ctx!.locale);
    expect(typeof ctx!.t('any.key')).toBe('string');
    // the default setLocale reports "no relaunch needed" and changes nothing
    await act(async () => { await expect(ctx!.setLocale(LOCALES[0]!)).resolves.toBe(false); });
    act(() => tree.unmount());
  });
});

describe('layout direction on the web build', () => {
  it('flips the document direction live, with no relaunch', async () => {
    const realOS = Platform.OS;
    const g = globalThis as { document?: { documentElement: { dir: string } } };
    const realDoc = g.document;
    g.document = { documentElement: { dir: 'ltr' } };
    Object.defineProperty(Platform, 'OS', { value: 'web', configurable: true });
    try {
      let ctx: ReturnType<typeof useI18n> | null = null;
      const Probe = () => { ctx = useI18n(); return <Text>{ctx.locale}</Text>; };
      let tree!: renderer.ReactTestRenderer;
      await act(async () => { tree = renderer.create(<I18nProvider><Probe /></I18nProvider>); });
      const rtl = RTL_LOCALES[0] ?? LOCALES[0]!;
      let needsRelaunch = true;
      await act(async () => { needsRelaunch = await ctx!.setLocale(rtl); });
      // the web build never needs a restart — it sets <html dir> and carries on
      expect(needsRelaunch).toBe(false);
      expect(['rtl', 'ltr']).toContain(g.document!.documentElement.dir);
      expect(ctx!.locale).toBe(rtl);
      await act(async () => tree.unmount());
    } finally {
      Object.defineProperty(Platform, 'OS', { value: realOS, configurable: true });
      g.document = realDoc;
    }
  });
});
